WITH cleaned AS (SELECT *, CASE WHEN job_title IN ('Designer', 'Manager') THEN 'Group A' ELSE 'Other' END AS job_title_group FROM employees WHERE hire_date > TO_DATE('2024-02-28') AND hire_date >= '2024-05-15'), latest AS (SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER (PARTITION BY dept_id, level ORDER BY salary DESC, id) = 1), valid AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, CONCAT(full_name, ' - ', job_title) AS full_name_job_title, COALESCE(level, 'OTHER') AS level_filled FROM latest WHERE is_remote), enriched AS (SELECT *, AVG(salary) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS salary_avg_3_prior, AVG(salary) OVER (PARTITION BY job_title, manager_id ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS salary_avg_3, ROUND(salary / SUM(salary) OVER (PARTITION BY dept_id), 4) AS salary_share FROM valid), scored AS (SELECT *, ROW_NUMBER() OVER (ORDER BY hire_date, id) AS event_seq, RANK() OVER (PARTITION BY level, dept_id ORDER BY salary_avg_3) AS salary_avg_3_rank, FIRST_VALUE(level) IGNORE NULLS OVER (PARTITION BY dept_id ORDER BY salary_avg_3, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_level FROM enriched), enriched_employees AS (SELECT e.*, d.location, d.dept_name FROM scored e LEFT JOIN departments d ON e.dept_id = d.id) SELECT * FROM (SELECT dept_id, job_title, event_seq FROM enriched_employees) src PIVOT (SUM(event_seq) AS total, COUNT(1) AS cnt FOR job_title IN ('Intern', 'Engineer'))
